'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={
'Serif':{sample:'Lora',fallback:'serif',description:'Small finishing strokes, called serifs, extend from the ends of letters. Compare their shapes and the contrast between thick and thin strokes.',notice:'Look for the small strokes at letter endings. Then compare round letters like o with straight letters like H.'},
'Sans Serif':{sample:'DM Sans',fallback:'sans-serif',description:'“Sans” means without: these letterforms have no serifs. Their shapes may be geometric, humanist, narrow, rounded, or many other things.',notice:'Notice the letter endings without serifs. Compare the shapes of a and g, and the openness of letters like e.'},
'Display':{sample:'Bodoni Moda',fallback:'serif',description:'Designed to make an impression at larger sizes. Display is a purpose, not one specific letter shape: a display font can also be a serif or sans serif.',notice:'Look for distinctive details that stand out at a large size. Reduce the size and judge whether those details remain readable.'},
'Handwriting':{sample:'Caveat',fallback:'cursive',description:'Letterforms that suggest writing by hand, from connected calligraphy to loose lettering. Not every handwriting family has connected letters.',notice:'Compare the slant, apparent pen strokes, and connections between letters. Try a short phrase and then a full paragraph.'},
'Monospace':{sample:'Space Mono',fallback:'monospace',description:'Every character occupies the same horizontal space. A narrow i and a wide W get equal room, creating a steady rhythm often used for code.',notice:'Compare iiiii with WWWWW. In a monospaced font, both strings occupy the same width.'}
};
const lessons=[
['Typeface, family, and face','A typeface is the visual design of a set of letters. A family groups its related styles. A face is a particular style, such as Lora Bold Italic. People often use “font” to mean any of these; technically it can refer to the file delivering a face.','Try: open a font’s details and switch between its available faces.'],
['Serif, sans serif, and the other types','Serif and sans serif describe letter construction. Handwriting suggests a method of making marks. Monospace describes character spacing. Display describes intended use. These labels overlap, and they are only a starting point, not the whole map of typography.','Try: choose each category and compare the same sentence.'],
['Weight, italic, and variable fonts','Weight controls how heavy strokes look. Common CSS values run from 100 to 900, but a family may offer only some of them. Italic is a separate style, often with redesigned letterforms. A variable font offers adjustable axes within a supported range, such as weight or width.','Try: compare Regular and Bold. Open details to see this family’s actual weights and variable axes.'],
['Size, letter spacing, and line height','Font size sets the size of the em square, not the exact height of visible letters. Letter spacing (tracking) adds space across characters. Line height controls the distance between text baselines. Kerning is different: it adjusts the space between particular pairs, such as A and V.','Try: change line height on a long sentence, then adjust letter spacing a little.'],
['Anatomy: x-height, counters, and contrast','X-height is the height of a lowercase x. Counters are spaces enclosed or partly enclosed by letters, such as o and e. Stroke contrast is the difference between thick and thin strokes. These details explain why fonts at the same size can feel very different.','Try: enter “Hamburgefontsiv a g x e o” and compare two families at the same size.'],
['Readability and choosing a font','There is no universal rule that serif or sans serif is easier to read. Size, spacing, contrast, language, and context all matter. Start with a font that supports your writing system, then test it with real text at the size and screen width people will use.','Try: compare a heading and a full paragraph. Save the fonts you want to revisit.']
];
let fonts=[],filtered=[],category='',limit=24,compare=new Set(),favorite=new Set(),loaded=new Map(),observer;
try{favorite=new Set(JSON.parse(localStorage.getItem('type-study-favorites')||'[]'));const prefs=JSON.parse(localStorage.getItem('type-study-prefs')||'{}');for(const id of ['explain','controlsToggle','lessonsToggle'])if(typeof prefs[id]==='boolean')$(id).checked=prefs[id]}catch{}
function preferences(){document.body.classList.toggle('no-explanations',!$('explain').checked);$('controls').hidden=!$('controlsToggle').checked;$('lessons').hidden=!$('lessonsToggle').checked;try{localStorage.setItem('type-study-prefs',JSON.stringify(Object.fromEntries(['explain','controlsToggle','lessonsToggle'].map(id=>[id,$(id).checked]))))}catch{}}
['explain','controlsToggle','lessonsToggle'].forEach(id=>$(id).addEventListener('change',preferences));preferences();
$('lessonList').innerHTML=lessons.map(([title,body,task],i)=>`<details><summary>${i+1}. ${title}</summary><p>${body}</p><p><em>${task}</em></p></details>`).join('');
$('lessonNav').onclick=()=>{$('lessonsToggle').checked=true;preferences();$('lessons').scrollIntoView({behavior:'smooth'});$('lessonList').querySelector('details').open=true};
const weightList=f=>Object.keys(f.fonts).filter(x=>!x.endsWith('i')).map(Number).sort((a,b)=>a-b);
function nearest(f,w){const values=weightList(f);return values.length?values.reduce((a,b)=>Math.abs(b-w)<Math.abs(a-w)?b:a):Number(Object.keys(f.fonts)[0].replace('i',''))}
function fontStyle(f,w=+$('weight').value){return `font-family:&quot;${esc(f.family)}&quot;,${types[f.category]?.fallback||'sans-serif'};font-weight:${nearest(f,w)};font-synthesis:none;font-style:${weightList(f).length?'normal':'italic'}`}
function ensureFont(f){if(loaded.has(f.family))return loaded.get(f.family);const promise=new Promise(resolve=>{const link=document.createElement('link');link.rel='stylesheet';const weights=weightList(f);const italic=Object.keys(f.fonts).filter(x=>x.endsWith('i')).map(x=>+x.slice(0,-1)).sort((a,b)=>a-b);let axis='';if(weights.length&&italic.length)axis='ital,wght@'+weights.map(w=>'0,'+w).concat(italic.map(w=>'1,'+w)).join(';');else if(weights.length)axis='wght@'+weights.join(';');else axis='ital,wght@'+italic.map(w=>'1,'+w).join(';');link.href='https://fonts.googleapis.com/css2?family='+encodeURIComponent(f.family).replace(/%20/g,'+')+':'+axis+'&display=swap';link.onload=async()=>{try{await document.fonts.load(`${weightList(f).length?'normal':'italic'} ${nearest(f,400)} 24px "${f.family}"`);resolve(true)}catch{resolve(false)}};link.onerror=()=>resolve(false);document.head.append(link)});loaded.set(f.family,promise);return promise}
function observe(){observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){const f=fonts.find(f=>f.family===e.target.dataset.family);ensureFont(f).then(ok=>{const status=e.target.querySelector('.load-status');if(status)status.textContent=ok?'':'Preview unavailable · fallback font shown'});observer.unobserve(e.target)}},{rootMargin:'200px'});document.querySelectorAll('.font-card').forEach(el=>observer.observe(el))}
function setCategory(cat){category=cat;limit=24;$('categoryTitle').textContent=cat?cat+' fonts':'Font library';$('categoryDescription').textContent=cat?types[cat].description:'Explore the complete catalogue, or choose a type above to learn its defining features.';document.querySelectorAll('.category').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===cat)));filter();}
function filter(){const q=$('search').value.trim().toLowerCase();filtered=fonts.filter(f=>(!category||f.category===category)&&(!$('favoritesOnly').checked||favorite.has(f.family))&&(!q||(f.family+' '+f.designers.join(' ')).toLowerCase().includes(q)));const sort=$('sort').value;filtered.sort(sort==='popular'?(a,b)=>a.popularity-b.popularity:sort==='new'?(a,b)=>b.dateAdded.localeCompare(a.dateAdded):sort==='za'?(a,b)=>b.family.localeCompare(a.family):(a,b)=>a.family.localeCompare(b.family));render()}
function render(){const visible=filtered.slice(0,limit);$('count').textContent=`${filtered.length.toLocaleString()} families · showing ${visible.length.toLocaleString()}`;$('fonts').innerHTML=visible.length?visible.map(f=>`<article class="font-card" data-family="${esc(f.family)}"><div class="card-top"><div><button class="font-name" data-detail="${esc(f.family)}">${esc(f.family)}</button><p class="meta">${esc(f.category)} · ${Object.keys(f.fonts).length} faces${f.axes.length?' · Variable':''} · <span class="actual-weight">Weight ${nearest(f,+$('weight').value)}</span></p></div><button class="save" data-save="${esc(f.family)}" aria-label="${favorite.has(f.family)?'Unsave':'Save'} ${esc(f.family)}" aria-pressed="${favorite.has(f.family)}">${favorite.has(f.family)?'Saved':'Save'}</button></div><p class="specimen" style="${fontStyle(f)}">${esc($('preview').value||f.family)}</p><p class="meta load-status" aria-live="polite">Loading font preview…</p><p class="font-explanation">${esc(types[f.category].notice)}</p><div class="card-bottom"><label><input type="checkbox" data-compare="${esc(f.family)}" ${compare.has(f.family)?'checked':''}> Compare</label><button data-detail="${esc(f.family)}">View family</button></div></article>`).join(''):'<p class="empty">No fonts match. Try a different search, type, or saved-font filter.</p>';$('loadMore').hidden=limit>=filtered.length;observe()}
$('search').oninput=()=>{limit=24;filter()};$('sort').onchange=filter;$('favoritesOnly').onchange=()=>{limit=24;filter()};$('allBtn').onclick=()=>setCategory('');$('loadMore').onclick=()=>{limit+=24;render()};
function specimenControls(){document.documentElement.style.setProperty('--size',$('size').value+'px');document.documentElement.style.setProperty('--tracking',+$('tracking').value/100+'em');document.documentElement.style.setProperty('--leading',+$('leading').value/10);$('sizeOut').textContent=$('size').value+' px';$('trackingOut').textContent=+$('tracking').value/100+' em';$('leadingOut').textContent=+$('leading').value/10;document.querySelectorAll('.font-card').forEach(card=>{const f=fonts.find(f=>f.family===card.dataset.family);card.querySelector('.specimen').textContent=$('preview').value||f.family;card.querySelector('.specimen').style.fontWeight=nearest(f,+$('weight').value);card.querySelector('.actual-weight').textContent='Weight '+nearest(f,+$('weight').value)})}
['preview','size','weight','tracking','leading'].forEach(id=>$(id).addEventListener('input',specimenControls));$('reset').onclick=()=>{$('preview').value='The quick brown fox jumps over the lazy dog.';$('size').value=36;$('weight').value=400;$('tracking').value=0;$('leading').value=14;specimenControls()};
$('fonts').onclick=e=>{const save=e.target.closest('[data-save]'),detail=e.target.closest('[data-detail]');if(save){const name=save.dataset.save;favorite.has(name)?favorite.delete(name):favorite.add(name);try{localStorage.setItem('type-study-favorites',JSON.stringify([...favorite]))}catch{}if($('favoritesOnly').checked)filter();else{save.textContent=favorite.has(name)?'Saved':'Save';save.setAttribute('aria-pressed',String(favorite.has(name)));save.setAttribute('aria-label',(favorite.has(name)?'Unsave ':'Save ')+name)}}if(detail)openDetail(fonts.find(f=>f.family===detail.dataset.detail))};
$('fonts').onchange=e=>{if(!e.target.dataset.compare)return;const name=e.target.dataset.compare;if(e.target.checked){if(compare.size>=3){e.target.checked=false;$('compareCount').textContent='3 selected · clear one to add another';return}compare.add(name)}else compare.delete(name);compareUI()};
function compareUI(){$('compareBar').hidden=!compare.size;$('compareCount').textContent=compare.size+' font'+(compare.size===1?'':'s')+' selected';$('openCompare').disabled=compare.size<2;document.querySelectorAll('[data-compare]').forEach(c=>c.checked=compare.has(c.dataset.compare))}
$('clearCompare').onclick=()=>{compare.clear();compareUI()};
function openDetail(f){ensureFont(f);const keys=Object.keys(f.fonts).sort((a,b)=>parseInt(a)-parseInt(b)||a.localeCompare(b));const initial=String(nearest(f,+$('weight').value));$('detailContent').innerHTML=`<p class="detail-meta">${esc(f.category)}</p><h2 id="detailTitle">${esc(f.family)}</h2><p class="detail-meta">Designed by ${esc(f.designers.join(', ')||'Google Fonts contributors')} · Added ${esc(f.dateAdded)}</p><p>${esc(types[f.category].description)}</p><div class="face-controls"><label>Available face<select id="face">${keys.map(k=>`<option value="${k}" ${k===initial?'selected':''}>${k.replace('i','')} ${k.endsWith('i')?'Italic':'Normal'}</option>`).join('')}</select></label><label>Specimen text<input id="detailText" value="${esc($('preview').value||f.family)}"></label></div><p id="detailSpecimen" class="detail-specimen" style="${fontStyle(f)}">${esc($('preview').value||f.family)}</p><h3>What to look for</h3><p>${esc(types[f.category].notice)}</p><h3>What this family includes</h3><p>${keys.length} faces. ${f.axes.length?'Variable axes: '+f.axes.map(a=>esc(a.tag)+' ('+a.min+'–'+a.max+')').join(', ')+'. A variable axis is an adjustable property; this workspace focuses on weight.':'No variable axes listed in this catalogue snapshot.'}</p><p>Writing-system subsets: ${esc(f.subsets.filter(s=>s!=='menu').join(', '))}. A subset describes coverage, not a guarantee that every character in a language is available.</p>${f.classifications?.length?'<p>Additional classifications: '+esc(f.classifications.join(', '))+'.</p>':''}<p><a href="https://fonts.google.com/specimen/${encodeURIComponent(f.family).replace(/%20/g,'+')}" target="_blank" rel="noopener">View this family on Google Fonts</a></p>`;const update=()=>{const key=$('face').value;const el=$('detailSpecimen');el.style.fontWeight=parseInt(key);el.style.fontStyle=key.endsWith('i')?'italic':'normal';el.textContent=$('detailText').value||f.family};$('face').onchange=update;$('detailText').oninput=update;update();$('detail').showModal()}
$('openCompare').onclick=()=>{const selected=[...compare].map(n=>fonts.find(f=>f.family===n));$('compareContent').className='compare-grid';$('compareContent').style.gridTemplateColumns=`repeat(${selected.length},minmax(0,1fr))`;$('compareContent').innerHTML=selected.map(f=>{ensureFont(f);return `<div class="compare-column"><h3>${esc(f.family)}</h3><p class="meta">${esc(f.category)} · Weight ${nearest(f,+$('weight').value)}</p><p class="specimen" style="${fontStyle(f)}">${esc($('preview').value||f.family)}</p><p class="specimen" style="${fontStyle(f)}">a g e o<br>Hamburgefontsiv<br>iiiii<br>WWWWW</p><p class="font-explanation">${esc(types[f.category].notice)}</p></div>`}).join('');$('comparison').showModal()};
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
// Vocabulary practice links apply supported controls without changing saved favorites.
const practiceParams=new URLSearchParams(location.search);
if(practiceParams.has('preview'))$('preview').value=practiceParams.get('preview').slice(0,2000);
for(const [id,min,max] of [['size',16,80],['tracking',-5,20],['leading',10,22]]){
 if(practiceParams.has(id)&&Number.isFinite(Number(practiceParams.get(id))))$(id).value=Math.min(max,Math.max(min,Number(practiceParams.get(id))));
}
if([...$('weight').options].some(o=>o.value===practiceParams.get('weight')))$('weight').value=practiceParams.get('weight');
if(Object.hasOwn(types,practiceParams.get('category')))category=practiceParams.get('category');
if(practiceParams.size){$('controlsToggle').checked=true;preferences();specimenControls()}
if(location.hash==='#lessons'){$('lessonsToggle').checked=true;preferences()}
(async()=>{try{const response=await fetch('fonts.json');if(!response.ok)throw Error('Catalogue unavailable');const data=await response.json();fonts=data.fonts;$('categories').innerHTML=Object.entries(types).map(([cat,t])=>`<button class="category" data-category="${cat}" aria-pressed="false"><span class="letters" style="font-family:'${t.sample}',${t.fallback}">Aa</span><strong>${cat}</strong><small>${fonts.filter(f=>f.category===cat).length} families</small></button>`).join('');$('categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b){setCategory(category===b.dataset.category?'':b.dataset.category);$('catalogue').scrollIntoView({behavior:'smooth'})}};for(const t of Object.values(types)){const f=fonts.find(f=>f.family===t.sample);if(f)ensureFont(f)}$('sourceNote').innerHTML=`${fonts.length.toLocaleString()} families from <a href="https://fonts.google.com/" target="_blank" rel="noopener">Google Fonts</a> · Catalogue snapshot ${data.updated}. Fonts load from Google as needed. Saved fonts and workspace preferences stay in this browser. Category explanations describe the type, not a unique review of each font.`;setCategory(category)}catch(e){$('count').textContent='Catalogue could not load';$('error').hidden=false;$('error').textContent='Please reload the page to try again.';$('loadMore').hidden=true}})();
